export function AvatarPickerSingle() {
  const [value, setValue] = useState<string>('');

  const selectedUser = PICKER_USERS.find(u => String(u.id) === value);

  return (
    <Select
      items={pickerItems}
      value={value}
      onValueChange={v => setValue(v as string)}>
      <SelectTrigger className="w-[280px]">
        <SelectValue placeholder="Select a person">
          {selectedUser ? (
            <span className="flex items-center gap-2">
              <Avatar size="xs">
                <AvatarImage src={selectedUser.avatar} />
                <AvatarFallback>{initials(selectedUser.name)}</AvatarFallback>
              </Avatar>
              <span className="truncate">{selectedUser.name}</span>
            </span>
          ) : null}
        </SelectValue>
      </SelectTrigger>

      <SelectContent>
        {PICKER_USERS.map(user => (
          <SelectItem key={user.id} value={String(user.id)}>
            <Avatar size="sm">
              <AvatarImage src={user.avatar} />
              <AvatarFallback>{initials(user.name)}</AvatarFallback>
            </Avatar>

            <SelectItemText>{user.name}</SelectItemText>

            <SelectItemIndicator>
              <Icon icon="check" className="size-4" />
            </SelectItemIndicator>
          </SelectItem>
        ))}
      </SelectContent>
    </Select>
  );
}

export function AvatarPickerMultiple() {
  const [value, setValue] = useState<string[]>([]);

  return (
    <Select
      multiple
      items={pickerItems}
      value={value}
      onValueChange={v => setValue(v as string[])}>
      <SelectTrigger className="w-[280px]">
        <SelectValue placeholder="Select people">
          {value.length > 0 ? (
            <span className="flex items-center gap-2">
              <Tag
                variant="secondary"
                size="xs"
                pill
                onRemove={e => {
                  e.stopPropagation();
                  setValue([]);
                }}>
                <span className="pl-1">{value.length}</span>
              </Tag>
              <span className="truncate">people selected</span>
            </span>
          ) : null}
        </SelectValue>
      </SelectTrigger>

      <SelectContent>
        {PICKER_USERS.map(user => (
          <SelectItem key={user.id} value={String(user.id)}>
            <Checkbox
              size="default"
              checked={value.includes(String(user.id))}
              onCheckedChange={() => {}}
              tabIndex={-1}
              className="pointer-events-none"
            />

            <Avatar size="sm">
              <AvatarImage src={user.avatar} />
              <AvatarFallback>{initials(user.name)}</AvatarFallback>
            </Avatar>

            <SelectItemText>{user.name}</SelectItemText>
          </SelectItem>
        ))}
      </SelectContent>
    </Select>
  );
}

