                  className={`${size.legendClass} ${legendGap}`}>
                  {size.label} ({density.label})
                </FieldLegend>

                <RadioGroup
                  defaultValue={ids[0]}
                  className={`${groupGap} ${density.padding}`}>
                  {ids.map(id => (
                    <Field key={id} orientation="horizontal">
                      <RadioGroupItem
                        value={id}
                        id={id}
                        size={size.radioSize}
                      />
                      <FieldLabel htmlFor={id} className={size.labelClass}>
                        Label
                      </FieldLabel>
                    </Field>
                  ))}
                </RadioGroup>
              </FieldSet>
            );
          })}
        </div>
      ))}
